import { promises as fs } from "node:fs";
import path from "node:path";
import { randomBytes } from "node:crypto";

export type BookStatus = "reading" | "finished";

export type Book = {
  id: string;
  title: string;
  author: string;
  status: BookStatus;
  notes: string;
  createdAt: string;
  finishedAt: string | null;
};

const DATA_DIR = path.join(process.cwd(), "data");
const DATA_FILE = path.join(DATA_DIR, "books.json");

async function ensureFile(): Promise<void> {
  await fs.mkdir(DATA_DIR, { recursive: true });
  try {
    await fs.access(DATA_FILE);
  } catch {
    await fs.writeFile(DATA_FILE, "[]", "utf8");
  }
}

async function readAll(): Promise<Book[]> {
  await ensureFile();
  const raw = await fs.readFile(DATA_FILE, "utf8");
  const parsed = JSON.parse(raw);
  if (!Array.isArray(parsed)) return [];
  return parsed as Book[];
}

async function writeAll(books: Book[]): Promise<void> {
  await ensureFile();
  const tmp = DATA_FILE + ".tmp-" + randomBytes(6).toString("hex");
  await fs.writeFile(tmp, JSON.stringify(books, null, 2), "utf8");
  await fs.rename(tmp, DATA_FILE);
}

function slugify(input: string): string {
  return input
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 60);
}

async function makeId(title: string): Promise<string> {
  const base = slugify(title) || "book";
  const existing = await readAll();
  const taken = new Set(existing.map((b) => b.id));
  if (!taken.has(base)) return base;
  for (let i = 0; i < 10; i++) {
    const suffix = randomBytes(2).toString("hex");
    const candidate = `${base}-${suffix}`;
    if (!taken.has(candidate)) return candidate;
  }
  return `${base}-${randomBytes(4).toString("hex")}`;
}

export async function listBooks(): Promise<{ reading: Book[]; finished: Book[] }> {
  const all = await readAll();
  const reading = all
    .filter((b) => b.status === "reading")
    .sort((a, b) => a.createdAt.localeCompare(b.createdAt));
  const finished = all
    .filter((b) => b.status === "finished")
    .sort((a, b) => (b.finishedAt ?? "").localeCompare(a.finishedAt ?? ""));
  return { reading, finished };
}

export async function getBook(id: string): Promise<Book | null> {
  const all = await readAll();
  return all.find((b) => b.id === id) ?? null;
}

export async function addBook(input: { title: string; author: string }): Promise<Book> {
  const title = input.title.trim();
  const author = input.author.trim();
  if (!title || !author) {
    throw new Error("Title and author are required");
  }
  const all = await readAll();
  const book: Book = {
    id: await makeId(title),
    title,
    author,
    status: "reading",
    notes: "",
    createdAt: new Date().toISOString(),
    finishedAt: null,
  };
  all.push(book);
  await writeAll(all);
  return book;
}

export async function markFinished(id: string): Promise<Book> {
  const all = await readAll();
  const idx = all.findIndex((b) => b.id === id);
  if (idx === -1) throw new Error("Book not found");
  all[idx] = {
    ...all[idx],
    status: "finished",
    finishedAt: new Date().toISOString(),
  };
  await writeAll(all);
  return all[idx];
}

export async function markReading(id: string): Promise<Book> {
  const all = await readAll();
  const idx = all.findIndex((b) => b.id === id);
  if (idx === -1) throw new Error("Book not found");
  all[idx] = { ...all[idx], status: "reading", finishedAt: null };
  await writeAll(all);
  return all[idx];
}

export async function updateNotes(id: string, notes: string): Promise<Book> {
  const all = await readAll();
  const idx = all.findIndex((b) => b.id === id);
  if (idx === -1) throw new Error("Book not found");
  all[idx] = { ...all[idx], notes };
  await writeAll(all);
  return all[idx];
}

export async function deleteBook(id: string): Promise<void> {
  const all = await readAll();
  await writeAll(all.filter((b) => b.id !== id));
}

