import type { Metadata } from "next";
import "./globals.css";

export const metadata: Metadata = {
  title: "Book tracker",
  description: "Keep track of what you're reading",
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <body>
        <header className="site-header">
          <a href="/" className="site-title">Book tracker</a>
        </header>
        <main className="site-main">{children}</main>
      </body>
    </html>
  );
}

:root {
  color-scheme: light dark;
  --fg: #1a1a1a;
  --fg-muted: #6b6b6b;
  --bg: #fafaf7;
  --surface: #ffffff;
  --border: #e3e3e0;
  --accent: #2f6f4f;
  --accent-soft: #e8f1ec;
  --danger: #a23b3b;
  --radius: 8px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --fg: #ededed;
    --fg-muted: #9a9a9a;
    --bg: #14140f;
    --surface: #1d1d18;
    --border: #2e2e28;
    --accent: #7cc6a0;
    --accent-soft: #1e2c25;
  }
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--fg);
  line-height: 1.5;
}

.site-header {
  border-bottom: 1px solid var(--border);
  padding: 1rem 1.5rem;
  background: var(--surface);
}

.site-title {
  font-weight: 600;
  font-size: 1.1rem;
  color: var(--fg);
  text-decoration: none;
}

.site-main {
  max-width: 760px;
  margin: 0 auto;
  padding: 1.5rem;
}

h1 {
  font-size: 1.5rem;
  margin: 0 0 1rem;
}

h2 {
  font-size: 1.15rem;
  margin: 2rem 0 0.75rem;
  color: var(--fg-muted);
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  font-size: 0.85rem;
}

.empty {
  color: var(--fg-muted);
  font-style: italic;
  padding: 0.5rem 0;
}

.book-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.book-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.75rem 1rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.book-item a {
  color: var(--fg);
  text-decoration: none;
  flex: 1;
  min-width: 0;
}

.book-item a:hover .book-title { text-decoration: underline; }

.book-title {
  font-weight: 600;
  display: block;
}

.book-author {
  color: var(--fg-muted);
  font-size: 0.9rem;
}

form.add-form {
  display: grid;
  grid-template-columns: 2fr 2fr auto;
  gap: 0.5rem;
  margin-bottom: 0.5rem;
}

@media (max-width: 520px) {
  form.add-form { grid-template-columns: 1fr; }
}

input[type="text"], textarea {
