"use server";

import { revalidatePath } from "next/cache";
import {
  addBook as addBookStore,
  deleteBook as deleteBookStore,
  markFinished as markFinishedStore,
  markReading as markReadingStore,
  updateNotes as updateNotesStore,
} from "@/lib/books";

export type ActionResult =
  | { ok: true }
  | { ok: false; error: string };

export async function addBookAction(formData: FormData): Promise<ActionResult> {
  const title = String(formData.get("title") ?? "").trim();
  const author = String(formData.get("author") ?? "").trim();
  if (!title || !author) {
    return { ok: false, error: "Title and author are required" };
  }
  try {
    await addBookStore({ title, author });
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : "Failed to add book" };
  }
  revalidatePath("/");
  return { ok: true };
}

export async function markFinishedAction(id: string): Promise<ActionResult> {
  try {
    await markFinishedStore(id);
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : "Failed to update" };
  }
  revalidatePath("/");
  revalidatePath(`/book/${id}`);
  return { ok: true };
}

export async function markReadingAction(id: string): Promise<ActionResult> {
  try {
    await markReadingStore(id);
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : "Failed to update" };
  }
  revalidatePath("/");
  revalidatePath(`/book/${id}`);
  return { ok: true };
}

export async function updateNotesAction(id: string, notes: string): Promise<ActionResult> {
  try {
    await updateNotesStore(id, notes);
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : "Failed to save notes" };
  }
  revalidatePath(`/book/${id}`);
  return { ok: true };
}

export async function deleteBookAction(id: string): Promise<ActionResult> {
  try {
    await deleteBookStore(id);
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : "Failed to delete" };
  }
  revalidatePath("/");
  revalidatePath(`/book/${id}`);
  return { ok: true };
}

"use client";

import { useState, useTransition } from "react";
import { addBookAction } from "@/app/actions";

export function AddBookForm() {
  const [error, setError] = useState<string | null>(null);
  const [pending, startTransition] = useTransition();

  function onSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(null);
    const form = event.currentTarget;
    const formData = new FormData(form);
    startTransition(async () => {
      const result = await addBookAction(formData);
      if (result.ok) {
        form.reset();
      } else {
        setError(result.error);
      }
    });
  }

  return (
    <form className="add-form" onSubmit={onSubmit}>
      <input
        type="text"
        name="title"
        placeholder="Title"
        required
        maxLength={200}
        disabled={pending}
      />
      <input
        type="text"
        name="author"
        placeholder="Author"
        required
        maxLength={200}
        disabled={pending}
      />
      <button type="submit" disabled={pending}>
        {pending ? "Adding..." : "Add book"}
      </button>
      {error && <p className="form-error" style={{ gridColumn: "1 / -1" }}>{error}</p>}
    </form>
  );
}

"use client";

import { useTransition } from "react";
import { useRouter } from "next/navigation";
import { markFinishedAction, markReadingAction, deleteBookAction } from "@/app/actions";

export function BookRowActions({ id, status }: { id: string; status: "reading" | "finished" }) {
  const [pending, startTransition] = useTransition();
  const router = useRouter();

  function onFinish() {
    startTransition(async () => {
      await markFinishedAction(id);
    });
  }

  function onUnfinish() {
    startTransition(async () => {
      await markReadingAction(id);
    });
  }

  function onDelete() {
    if (!confirm("Delete this book? This can't be undone.")) return;
    startTransition(async () => {
      const result = await deleteBookAction(id);
      if (result.ok) router.refresh();
    });
  }

  if (status === "reading") {
    return (
      <div className="actions" style={{ margin: 0 }}>
        <button type="button" onClick={onFinish} disabled={pending} className="secondary">
          Mark finished
        </button>
        <button type="button" onClick={onDelete} disabled={pending} className="danger" aria-label="Delete book">
          Delete
        </button>
      </div>
    );
  }

  return (
    <div className="actions" style={{ margin: 0 }}>
      <button type="button" onClick={onUnfinish} disabled={pending} className="secondary">
        Move to reading
      </button>
      <button type="button" onClick={onDelete} disabled={pending} className="danger" aria-label="Delete book">
        Delete
      </button>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { updateNotesAction, markFinishedAction, markReadingAction, deleteBookAction } from "@/app/actions";
import { useRouter } from "next/navigation";

export function BookDetailActions({
  id,
  status,
  initialNotes,
}: {
  id: string;
  status: "reading" | "finished";
  initialNotes: string;
}) {
  const [notes, setNotes] = useState(initialNotes);
  const [pending, startTransition] = useTransition();
  const [feedback, setFeedback] = useState<string | null>(null);
  const router = useRouter();

  function saveNotes() {
    setFeedback(null);
    startTransition(async () => {
      const result = await updateNotesAction(id, notes);
      setFeedback(result.ok ? "Notes saved" : result.error);
    });
  }

  function toggleStatus() {
    setFeedback(null);
    startTransition(async () => {
      const result = status === "reading" ? await markFinishedAction(id) : await markReadingAction(id);
      if (!result.ok) setFeedback(result.error);
    });
  }

  function onDelete() {
    if (!confirm("Delete this book? This can't be undone.")) return;
    startTransition(async () => {
      const result = await deleteBookAction(id);
      if (result.ok) router.push("/");
    });
  }

  return (
    <>
      <textarea
        value={notes}
        onChange={(e) => setNotes(e.target.value)}
        placeholder="Your notes... what did you think? Quotes, ideas, anything."
        disabled={pending}
      />
      <div className="actions">
        <button type="button" onClick={saveNotes} disabled={pending}>
          {pending ? "Saving..." : "Save notes"}
        </button>
        <button type="button" onClick={toggleStatus} disabled={pending} className="secondary">
          {status === "reading" ? "Mark finished" : "Move to reading"}
        </button>
        <button type="button" onClick={onDelete} disabled={pending} className="danger">
          Delete
        </button>
      </div>
      {feedback && <p className="form-error">{feedback}</p>}
    </>
  );
}

import Link from "next/link";
import { listBooks } from "@/lib/books";
import { AddBookForm } from "@/components/AddBookForm";
import { BookRowActions } from "@/components/BookRowActions";

export const dynamic = "force-dynamic";

export default async function HomePage() {
  const { reading, finished } = await listBooks();

  return (
    <>
      <h1>Books</h1>

      <section>
        <h2>Add a book</h2>
        <AddBookForm />
      </section>

      <section>
        <h2>Currently reading ({reading.length})</h2>
        {reading.length === 0 ? (
          <p className="empty">Nothing here yet. Add a book above to get started.</p>
        ) : (
          <ul className="book-list">
            {reading.map((book) => (
              <li className="book-item" key={book.id}>
                <Link href={`/book/${book.id}`}>
                  <span className="book-title">{book.title}</span>
                  <span className="book-author">{book.author}</span>
                </Link>
                <BookRowActions id={book.id} status={book.status} />
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2>Finished ({finished.length})</h2>
        {finished.length === 0 ? (
          <p className="empty">No finished books yet.</p>
        ) : (
          <ul className="book-list">
            {finished.map((book) => (
              <li className="book-item" key={book.id}>
                <Link href={`/book/${book.id}`}>
                  <span className="book-title">{book.title}</span>
                  <span className="book-author">{book.author}</span>
                </Link>
                <BookRowActions id={book.id} status={book.status} />
              </li>
            ))}
          </ul>
        )}
      </section>
    </>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { getBook } from "@/lib/books";
import { BookDetailActions } from "@/components/BookDetailActions";

export const dynamic = "force-dynamic";

export default async function BookPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) notFound();

  const finishedDate = book.finishedAt
    ? new Date(book.finishedAt).toLocaleDateString(undefined, {
        year: "numeric",
        month: "short",
        day: "numeric",
      })
    : null;

  return (
    <>
      <Link href="/" className="back-link">&larr; All books</Link>
      <article className="detail">
        <h1>
          {book.title}
          <span className={`badge ${book.status === "finished" ? "finished" : ""}`}>
            {book.status === "finished" ? "Finished" : "Reading"}
          </span>
        </h1>
        <p className="meta">
          by {book.author}
          {finishedDate && <> &middot; finished {finishedDate}</>}
        </p>
        <p className="meta">
          Share: <span className="share-link">/book/{book.id}</span>
        </p>

        <hr />

        <BookDetailActions
          id={book.id}
          status={book.status}
          initialNotes={book.notes}
        />
      </article>
    </>
  );
}

import Link from "next/link";

export default function NotFound() {
  return (
    <>
      <Link href="/" className="back-link">&larr; All books</Link>
      <article className="detail">
        <h1>Book not found</h1>
        <p className="meta">The book you're looking for doesn't exist (or was deleted).</p>
      </article>
    </>
  );
}

